4	--- /dev/null
5	+++ b/apps/obsidian/src/components/canvas/TextLinkDialog.tsx
6	@@ -0,0 +1,228 @@
7	+import { useCallback, useEffect, useRef, useState } from "react";
8	+import {
9	+  TLBaseShape,
10	+  TLShape,
11	+  TldrawUiButton,
12	+  TldrawUiButtonLabel,
13	+  TldrawUiDialogBody,
14	+  TldrawUiDialogCloseButton,
15	+  TldrawUiDialogFooter,
16	+  TldrawUiDialogHeader,
17	+  TldrawUiDialogTitle,
18	+  TldrawUiInput,
19	+  track,
20	+  useEditor,
21	+} from "tldraw";
22	+import {
23	+  getTextShapeLinkUrl,
24	+  isAllowedTextLinkUrl,
25	+  isObsidianUrl,
26	+} from "~/components/canvas/utils/textShapeLink";
27	+
28	+type ShapeWithUrl = TLBaseShape<string, { url: string }>;
29	+
30	+// Text shapes keep their link in `meta` so the stock props schema is untouched;
31	+// every other shape type uses tldraw's own `props.url`.
32	+const isTextShape = (shape: TLShape): boolean => shape.type === "text";
33	+
34	+const linkPatch = (shape: TLShape, url: string) =>
35	+  isTextShape(shape) ? { meta: { url } } : { props: { url } };
36	+
37	+const readLinkUrl = (shape: TLShape): string =>
38	+  isTextShape(shape)
39	+    ? getTextShapeLinkUrl(shape)
40	+    : (((shape.props as { url?: unknown }).url as string | undefined) ?? "");
41	+
42	+// Declared as a function property rather than reusing TLUiDialogProps, whose
43	+// method-shorthand onClose trips @typescript-eslint/unbound-method.
44	+type TextLinkDialogProps = { onClose: () => void };
45	+
46	+type UrlValidity = { isValid: boolean; hasProtocol: boolean };
47	+
48	+// Bookmarks link their title with a raw <a href>, not HyperlinkButton, so a
49	+// page link there would reach the OS handler and skip the vault check.
50	+const acceptsPageLinks = (shapeType: string): boolean =>
51	+  shapeType !== "bookmark";
52	+
53	+// Every shape type uses tldraw's linkUrl, patched to accept obsidian://open links.
54	+const validateUrl = (url: string, shapeType: string): UrlValidity => {
55	+  // Kept away from the https:// fallback, which would accept `https://obsidian://…`.
56	+  if (isObsidianUrl(url)) {
57	+    const isValid = acceptsPageLinks(shapeType) && isAllowedTextLinkUrl(url);
58	+    return { isValid, hasProtocol: isValid };
59	+  }
60	+  if (isAllowedTextLinkUrl(url)) return { isValid: true, hasProtocol: true };
61	+  if (isAllowedTextLinkUrl(`https://${url}`))
62	+    return { isValid: true, hasProtocol: false };
63	+  return { isValid: false, hasProtocol: false };
64	+};
65	+
66	+// A fork of tldraw's EditLinkDialog, which is not exported. Copy differs: the
67	+// original's msg() keys are inlined, as this app has no i18n layer.
68	+export const TextLinkDialog = track(({ onClose }: TextLinkDialogProps) => {
69	+  const editor = useEditor();
70	+  const selectedShape = editor.getOnlySelectedShape();
71	+
72	+  const canEditLink =
73	+    selectedShape &&
74	+    (isTextShape(selectedShape) ||
75	+      ("url" in selectedShape.props &&
76	+        typeof selectedShape.props.url === "string"));
77	+
78	+  if (!canEditLink) return null;
79	+
80	+  return (
81	+    <TextLinkDialogInner
82	+      key={selectedShape.id}
83	+      onClose={onClose}
84	+      selectedShape={selectedShape as ShapeWithUrl}
85	+    />
86	+  );
87	+});
88	+
89	+const TextLinkDialogInner = track(
90	+  ({
91	+    onClose,
92	+    selectedShape,
93	+  }: TextLinkDialogProps & { selectedShape: ShapeWithUrl }) => {
94	+    const editor = useEditor();
95	+    const rInput = useRef<HTMLInputElement | null>(null);
96	+    const shapeType = selectedShape.type;
97	+
98	+    useEffect(() => {
99	+      editor.timers.requestAnimationFrame(() => rInput.current?.focus());
100	+    }, [editor]);
101	+
102	+    const rInitialValue = useRef(readLinkUrl(selectedShape));
103	+
104	+    const [urlInputState, setUrlInputState] = useState(() => {
105	+      const initialUrl = readLinkUrl(selectedShape);
106	+      const result = validateUrl(initialUrl, shapeType);
107	+      const initialValue = result.isValid
108	+        ? result.hasProtocol
109	+          ? initialUrl
110	+          : `https://${initialUrl}`
111	+        : "https://";
112	+      return { actual: initialValue, safe: initialValue, valid: true };
113	+    });
114	+
115	+    const handleChange = useCallback(
116	+      (rawValue: string) => {
117	+        // Drop the prefilled https:// when a full URL is pasted after it.
118	+        const fixedRawValue = rawValue.replace(
119	+          /https?:\/\/((?:https?|obsidian):\/\/)/i,
120	+          (_match, arg1: string) => arg1,
121	+        );
122	+        const result = validateUrl(fixedRawValue, shapeType);
123	+        const safeValue = result.isValid
124	+          ? result.hasProtocol
125	+            ? fixedRawValue
126	+            : `https://${fixedRawValue}`
127	+          : "https://";
128	+
129	+        setUrlInputState({
130	+          actual: fixedRawValue,
131	+          safe: safeValue,
132	+          valid: result.isValid,
133	+        });
134	+      },
135	+      [shapeType],
136	+    );
137	+
138	+    const handleClear = useCallback(() => {
139	+      const onlySelectedShape = editor.getOnlySelectedShape();
140	+      if (!onlySelectedShape) return;
141	+      editor.updateShapes([
142	+        {
143	+          id: onlySelectedShape.id,
144	+          type: onlySelectedShape.type,
145	+          ...linkPatch(onlySelectedShape, ""),
146	+        },
147	+      ]);
148	+      onClose();
149	+    }, [editor, onClose]);
150	+
151	+    const handleComplete = useCallback(() => {
152	+      // Enter reaches this even while Save is disabled, and the fallback
153	+      // "https://" fails both validators.
154	+      if (!urlInputState.valid) return;
155	+      const onlySelectedShape = editor.getOnlySelectedShape();
156	+      if (!onlySelectedShape) return;
157	+      if (readLinkUrl(onlySelectedShape) !== urlInputState.safe) {
158	+        editor.updateShapes([
159	+          {
160	+            id: onlySelectedShape.id,
161	+            type: onlySelectedShape.type,
162	+            ...linkPatch(onlySelectedShape, urlInputState.safe),
163	+          },
164	+        ]);
165	+      }
166	+      onClose();
167	+    }, [editor, onClose, urlInputState]);
168	+
169	+    const handleCancel = useCallback(() => {
170	+      onClose();
171	+    }, [onClose]);
172	+
173	+    const isRemoving = rInitialValue.current && !urlInputState.valid;
174	+
175	+    return (
176	+      <>
177	+        <TldrawUiDialogHeader>
178	+          <TldrawUiDialogTitle>Edit link</TldrawUiDialogTitle>
179	+          <TldrawUiDialogCloseButton />
180	+        </TldrawUiDialogHeader>
181	+        <TldrawUiDialogBody>
182	+          <div className="tlui-edit-link-dialog">
183	+            <TldrawUiInput
184	+              ref={rInput}
185	+              className="tlui-edit-link-dialog__input"
186	+              label="edit-link-dialog.url"
187	+              autoFocus
188	+              autoSelect
189	+              placeholder="https://example.com"
190	+              value={urlInputState.actual}
191	+              onValueChange={handleChange}
192	+              onComplete={handleComplete}
193	+              onCancel={handleCancel}
194	+            />
195	+            <div>
196	+              {!urlInputState.valid
197	+                ? "Invalid URL"
198	+                : acceptsPageLinks(shapeType)
199	+                  ? "Enter a URL, or an obsidian:// link to a page."
200	+                  : "Enter a URL."}
201	+            </div>
202	+          </div>
203	+        </TldrawUiDialogBody>
204	+        <TldrawUiDialogFooter className="tlui-dialog__footer__actions">
205	+          <TldrawUiButton
206	+            type="normal"
207	+            onClick={handleCancel}
208	+            onTouchEnd={handleCancel}
209	+          >
210	+            <TldrawUiButtonLabel>Cancel</TldrawUiButtonLabel>
211	+          </TldrawUiButton>
212	+          {isRemoving ? (
213	+            <TldrawUiButton
214	+              type="danger"
215	+              onClick={handleClear}
216	+              onTouchEnd={handleClear}
217	+            >
218	+              <TldrawUiButtonLabel>Clear</TldrawUiButtonLabel>
219	+            </TldrawUiButton>
220	+          ) : (
221	+            <TldrawUiButton
222	+              type="primary"
223	+              disabled={!urlInputState.valid}
224	+              onClick={handleComplete}
225	+              onTouchEnd={handleComplete}
226	+            >
227	+              <TldrawUiButtonLabel>Save</TldrawUiButtonLabel>
228	+            </TldrawUiButton>
229	+          )}
230	+        </TldrawUiDialogFooter>
231	+      </>
232	+    );
233	+  },
234	+);
