299	@@ -0,0 +1,59 @@
300	+import { HyperlinkButton, useEditor, useValue, TLShapeId } from "tldraw";
301	+import { getTextShapeLinkUrl } from "~/components/canvas/utils/textShapeLink";
302	+
303	+// Matches tldraw's own HyperlinkButton, which hides itself when zoomed out.
304	+const HIDE_BELOW_ZOOM = 0.32;
305	+
306	+type TextLink = { id: TLShapeId; url: string; left: number; top: number };
307	+
308	+// Rendered here, not on a custom shape util, so the stock text shape stays
309	+// untouched -- at the cost of rotation, frame clipping and stacking fidelity.
310	+export const TextLinkOverlay = () => {
311	+  const editor = useEditor();
312	+
313	+  const links = useValue<TextLink[]>(
314	+    "textShapeLinks",
315	+    () => {
316	+      if (editor.getZoomLevel() < HIDE_BELOW_ZOOM) return [];
317	+      const viewport = editor.getViewportPageBounds();
318	+      return editor.getCurrentPageShapes().flatMap<TextLink>((shape) => {
319	+        if (shape.type !== "text" || editor.isShapeHidden(shape)) return [];
320	+        const url = getTextShapeLinkUrl(shape);
321	+        if (!url) return [];
322	+        const bounds = editor.getShapePageBounds(shape.id);
323	+        if (!bounds || !viewport.includes(bounds)) return [];
324	+        const topRight = editor.pageToViewport({
325	+          x: bounds.maxX,
326	+          y: bounds.minY,
327	+        });
328	+        const bottomRight = editor.pageToViewport({
329	+          x: bounds.maxX,
330	+          y: bounds.maxY,
331	+        });
332	+        return [
333	+          {
334	+            id: shape.id,
335	+            url,
336	+            left: topRight.x,
337	+            top: (topRight.y + bottomRight.y) / 2,
338	+          },
339	+        ];
340	+      });
341	+    },
342	+    [editor],
343	+  );
344	+
345	+  return (
346	+    <div className="dg-text-link-overlay">
347	+      {links.map(({ id, url, left, top }) => (
348	+        <div
349	+          key={id}
350	+          className="dg-text-link-anchor"
351	+          style={{ left: `${left}px`, top: `${top}px` }}
352	+        >
353	+          <HyperlinkButton url={url} />
354	+        </div>
355	+      ))}
356	+    </div>
357	+  );
358	+};
