420	@@ -0,0 +1,66 @@
421	+import type { Editor } from "tldraw";
422	+import DiscourseGraphPlugin from "~/index";
423	+import {
424	+  parseObsidianOpenUrl,
425	+  resolveObsidianUrlToFile,
426	+} from "~/components/canvas/utils/externalContentHandlers";
427	+import {
428	+  openFileInNewLeaf,
429	+  openFileInNewTab,
430	+  openFileInSidebar,
431	+} from "~/components/canvas/utils/openFileUtils";
432	+import { showToast } from "~/components/canvas/utils/toastUtils";
433	+import { isObsidianUrl } from "~/components/canvas/utils/textShapeLink";
434	+
435	+type NavigateLinkDetail = {
436	+  url: string;
437	+  metaKey: boolean;
438	+  ctrlKey: boolean;
439	+  altKey: boolean;
440	+};
441	+
442	+// Patched tldraw dispatches this from every HyperlinkButton, so one listener
443	+// covers text-shape links and geo/note/image links alike.
444	+export const NAVIGATE_LINK_EVENT = "tldraw.navigate-link";
445	+
446	+export const registerLinkNavigation = (
447	+  editor: Editor,
448	+  plugin: DiscourseGraphPlugin,
449	+): (() => void) => {
450	+  const container = editor.getContainer();
451	+
452	+  const onNavigate = (event: Event) => {
453	+    const { url, metaKey, ctrlKey, altKey } = (
454	+      event as CustomEvent<NavigateLinkDetail>
455	+    ).detail;
456	+    if (!isObsidianUrl(url)) return;
457	+    // Cancelling tells tldraw to preventDefault, so the URI never reaches the
458	+    // OS handler and we keep the cross-vault check below.
459	+    event.preventDefault();
460	+
461	+    // The validator parses with `new URL`, so geo links may be stored as
462	+    // `Obsidian://…` or with leading spaces; the parser expects the normal form.
463	+    const parsed = parseObsidianOpenUrl(new URL(url).toString());
464	+    const file = parsed ? resolveObsidianUrlToFile(plugin, parsed) : null;
465	+    if (!file) {
466	+      showToast({
467	+        severity: "warning",
468	+        title: "Cannot open link",
469	+        description: "The linked file is not in this vault",
470	+      });
471	+      return;
472	+    }
473	+
474	+    // Mirrors the discourse-node gestures in TldrawViewComponent.
475	+    const open = altKey
476	+      ? openFileInNewLeaf
477	+      : metaKey || ctrlKey
478	+        ? openFileInNewTab
479	+        : openFileInSidebar;
480	+    void open(plugin.app, file);
481	+    editor.selectNone();
482	+  };
483	+
484	+  container.addEventListener(NAVIGATE_LINK_EVENT, onNavigate);
485	+  return () => container.removeEventListener(NAVIGATE_LINK_EVENT, onNavigate);
486	+};
487	diff --git a/apps/obsidian/src/components/canvas/utils/textShapeLink.ts b/apps/obsidian/src/components/canvas/utils/textShapeLink.ts
