489	index 00000000..4c9159fd
490	--- /dev/null
491	+++ b/apps/obsidian/src/components/canvas/utils/textShapeLink.ts
492	@@ -0,0 +1,26 @@
493	+import { T, type TLShape } from "tldraw";
494	+
495	+// The patched tldraw validator is the single definition of a valid link, so geo
496	+// shapes and text shapes agree on what obsidian:// forms are accepted.
497	+export const isAllowedTextLinkUrl = (value: string): boolean =>
498	+  T.linkUrl.isValid(value);
499	+
500	+export const isObsidianUrl = (url: string): boolean => {
501	+  try {
502	+    return new URL(url).protocol.toLowerCase() === "obsidian:";
503	+  } catch {
504	+    return false;
505	+  }
506	+};
507	+
508	+// Returns the parsed form: `new URL` strips leading control characters, so a
509	+// raw value could pass the validator and fail a prefix test further on.
510	+export const getTextShapeLinkUrl = (shape: TLShape): string => {
511	+  const raw = (shape.meta as { url?: unknown }).url;
